-- SafetyTraining v20.061
-- First-aid extended evidence enrichment: trauma, medical emergencies, exposures and Group A scenarios.
-- Creates draft LU v2; published v1 compositions remain unchanged.

insert into public.training_sources(source_key,authority,title,source_type,canonical_url,publication_date,checked_on,license_kind,reuse_policy,normative_status,topics,notes,metadata)
values('inail-primo-soccorso-chimico-2025','INAIL','Rischio chimico sui luoghi di lavoro - manuale di primo soccorso in caso di infortunio','technical_manual','https://www.inail.it/portale/it/inail-comunica/news/notizia.2025.01.rischio-chimico-sui-luoghi-di-lavoro-online-un-manuale-di-primo-soccorso-in-caso-di-infortunio.html',date '2025-01-27',date '2026-10-15','institutional_terms','facts_and_original_didactic_rewrite','supporting',array['rischio chimico','primo soccorso','SDS','esposizione','ustioni chimiche'],'Fonte INAIL 2025 per primo intervento in caso di esposizione accidentale ad agenti chimici; usare SDS e informazioni specifiche della sostanza, senza copiare il manuale.',jsonb_build_object('priority','high_evidence'))
on conflict (source_key) do update set authority=excluded.authority,title=excluded.title,source_type=excluded.source_type,canonical_url=excluded.canonical_url,publication_date=excluded.publication_date,checked_on=excluded.checked_on,license_kind=excluded.license_kind,reuse_policy=excluded.reuse_policy,normative_status=excluded.normative_status,topics=excluded.topics,notes=excluded.notes,metadata=excluded.metadata,updated_at=now();

with base as (
 select lu.id learning_unit_id,lu.stable_key,v.content
 from public.learning_units lu
 join lateral (select content from public.learning_unit_versions luv where luv.learning_unit_id=lu.id and luv.status='published' order by version_number desc limit 1) v on true
 where lu.stable_key in ('primo_soccorso:traumi-scheletro-colonna','primo_soccorso:traumi-torace-addome','primo_soccorso:emergenze-mediche','primo_soccorso:ustioni-intossicazioni-temperatura','primo_soccorso:gruppo-a-rischi-specifici','primo_soccorso:gruppo-a-scenari-complessi')
), enriched as (
 select learning_unit_id,stable_key,
  content || jsonb_build_object('didactic_version','first-aid-v2','quality',coalesce(content->'quality','{}'::jsonb)||jsonb_build_object('teacher_ready',true,'learner_ready',true,'scenario_based',true,'practical_transfer_required',true),'source_audit',jsonb_build_object('status','reviewed','checked_on','2026-10-15','normative_validation','D.M. 388/2003','reuse_policy','reference_and_original_rewrite'),'delivery_note','Il materiale digitale sviluppa riconoscimento, priorità e comunicazione. Tecniche manuali, immobilizzazione, rianimazione e uso di presidi richiedono dimostrazione/addestramento pratico secondo il corso e le indicazioni del formatore.')
  || case stable_key
   when 'primo_soccorso:traumi-scheletro-colonna' then jsonb_build_object('spine_limb_trauma_lab',jsonb_build_object('title','Trauma: prima di muovere, chiediti perché','red_flags',jsonb_build_array('caduta dall’alto o energia significativa','dolore importante a collo/schiena','alterazione di sensibilità o movimento riferita','deformità evidente','trauma cranico con alterazione dello stato generale','peggioramento progressivo'),'decision_rule','Dopo un trauma importante evitare spostamenti non necessari e manovre improvvisate; chiamare i soccorsi e applicare solo tecniche apprese, salvo pericolo immediato della scena che imponga di agire secondo addestramento/indicazioni.','scenario','Lavoratore caduto da scala, cosciente, lamenta dolore cervicale e vuole alzarsi: il corsista deve organizzare sicurezza, allertamento, rassicurazione/monitoraggio e impedire prove di movimento non necessarie.','do_not',jsonb_build_array('rimettere in asse arti o articolazioni','far camminare per testare','rimuovere casco o altri presidi senza necessità/addestramento','improvvisare immobilizzazioni complesse')))
   when 'primo_soccorso:traumi-torace-addome' then jsonb_build_object('chest_abdomen_trauma_lab',jsonb_build_object('title','Trauma chiuso/aperto: riconosci il potenziale di gravità anche se i segni esterni sono modesti','observe',jsonb_build_array('dinamica dell’evento','difficoltà respiratoria','dolore importante','pallore/sudorazione o peggioramento','ferite evidenti','alterazione di coscienza'),'sequence',jsonb_build_array('sicurezza della scena','allertamento precoce nei traumi significativi','posizione/assistenza secondo condizioni, addestramento e indicazioni della centrale','non somministrare cibo, bevande o farmaci di iniziativa','monitorare respirazione, risposta e cambiamenti','consegnare dinamica e osservazioni ai soccorritori'),'scenario','Urto toracico/addominale con pochi segni esterni ma dolore crescente: decidere perché non basta vedere poco per escludere una situazione seria.'))
   when 'primo_soccorso:emergenze-mediche' then jsonb_build_object('medical_emergency_pattern_lab',jsonb_build_object('title','Riconosci pattern di allarme senza fare diagnosi','patterns',jsonb_build_array('dolore/oppressione toracica o difficoltà respiratoria importante','segni neurologici improvvisi o alterazione della parola/movimento','convulsione o perdita di coscienza','reazione allergica con difficoltà respiratoria/gonfiore significativo','alterazione importante dello stato generale o rapido peggioramento'),'task','Per ogni scenario dire: quali segni descrivo, quando attivo i soccorsi, cosa monitoro, quali informazioni preparo. Non è richiesto assegnare una diagnosi.','anti_delay_rule','Segni critici o rapido peggioramento richiedono attivazione precoce del sistema di emergenza; non attendere di capire esattamente cos’è prima di chiamare.','medication_boundary','Non somministrare farmaci di propria iniziativa. Eventuali terapie personali dell’infortunato sono gestite secondo procedure, indicazioni sanitarie e formazione applicabile.'))
   when 'primo_soccorso:ustioni-intossicazioni-temperatura' then jsonb_build_object('exposure_decision_lab',jsonb_build_object('title','Prima proteggi il soccorritore, poi identifica l’esposizione e usa l’informazione specifica','routes',jsonb_build_array('contatto cutaneo','contatto oculare','inalazione','ingestione','esposizione termica/calore','freddo'),'chemical_sequence',jsonb_build_array('non entrare in atmosfera/area non sicura','identifica sostanza/prodotto senza esporsi','recupera SDS/etichetta/procedura se disponibile','attiva soccorso sanitario/centro competente secondo procedura e riferisci sostanza e via di esposizione','applica solo decontaminazione/primo intervento previsti dalla formazione e dalle informazioni specifiche','non provocare vomito e non usare neutralizzanti/rimedi improvvisati'),'scenario','Schizzo di prodotto chimico con etichetta disponibile: il corsista deve proteggersi, recuperare SDS, identificare via di esposizione, chiamare e seguire indicazioni specifiche invece di scegliere un rimedio generico.','source_note','INAIL 2025 sottolinea che le misure di primo soccorso sono specifiche per sostanza e via di esposizione e che la SDS contiene informazioni da rendere accessibili sul luogo di lavoro.'),'evidence_sources',jsonb_build_array(jsonb_build_object('authority','INAIL','title','Rischio chimico sui luoghi di lavoro - primo soccorso in caso di infortunio','url','https://www.inail.it/portale/it/inail-comunica/news/notizia.2025.01.rischio-chimico-sui-luoghi-di-lavoro-online-un-manuale-di-primo-soccorso-in-caso-di-infortunio.html','use','chemical_first_aid_reference','checked_on','2026-10-15')))
   when 'primo_soccorso:gruppo-a-rischi-specifici' then jsonb_build_object('group_a_risk_mapping_lab',jsonb_build_object('title','Il primo soccorso deve assomigliare ai rischi reali dell’azienda','map_fields',jsonb_build_array('reparto/attività','evento plausibile','pericolo residuo per soccorritori','numero potenziale di coinvolti','accesso/tempo dei soccorsi esterni','presidi/informazioni necessarie','competenze pratiche da esercitare','chi mette in sicurezza impianto/area','punto di incontro soccorsi','scenario esercitativo'),'examples',jsonb_build_array('agente chimico specifico','energia elettrica','schiacciamento/intrappolamento','lavori isolati o remoti','ustioni importanti','più infortunati'),'output_required','Una scheda di scenario aziendale Gruppo A collegata a DVR, piano di emergenza/primo soccorso e addestramento.'),'teacher_rule','Non trasformare il modulo Gruppo A in un elenco universale: selezionare scenari coerenti con rischi, distanze dai soccorsi e organizzazione reale dell’azienda.')
   when 'primo_soccorso:gruppo-a-scenari-complessi' then jsonb_build_object('complex_incident_lab',jsonb_build_object('title','Più persone, più pericoli, risorse limitate: organizza prima di improvvisare','sequence',jsonb_build_array('ferma l’ingresso nella zona non sicura','attiva 112/118 e soccorsi/risorse interne necessarie','stima numero di coinvolti e pericoli senza esporsi','assegna compiti semplici e riconoscibili agli addetti disponibili','prioritizza condizioni critiche entro la formazione ricevuta','organizza accesso e punto di incontro dei soccorsi','mantieni comunicazione e aggiornamenti','chiudi con debrief organizzativo'),'scenario','Due lavoratori coinvolti, uno cosciente con trauma e uno non responsivo, mentre una fonte di rischio non è ancora completamente isolata: la squadra deve decidere cosa NON fare, chi chiama, chi mette in sicurezza, chi prepara il DAE/presidi e chi guida i soccorsi.','debrief_fields',jsonb_build_array('cosa ha ritardato il soccorso','informazioni mancanti','ruoli confusi','presidi/accessi problematici','barriere organizzative da correggere','azione, responsabile, scadenza, verifica')),'coordination_principle','In uno scenario complesso la qualità della risposta dipende anche da organizzazione, comunicazione e accessibilità dei soccorsi, non solo dalla singola manovra.')
   end as new_content
 from base
)
insert into public.learning_unit_versions(learning_unit_id,version_number,status,content,content_hash,published_at)
select learning_unit_id,2,'draft',new_content,md5(new_content::text),null from enriched
on conflict (learning_unit_id,version_number) do update set status='draft',content=excluded.content,content_hash=excluded.content_hash,published_at=null;

